let fuzzClosure = {
extension Range<AbsolutePosition> {
  /// Shift the range `utf8Offset` bytes to the right, ie. add `utf8Offset` to the upper and lower bound.
  func advanced(by utf8Offset: Int) -> /*
*/Range<AbsolutePosition> {
    return self.lowerBound.advanced(by: utf8Offset)..<self. /* c */ upperBound.advanced(by: utf8Offset)
  }
}
}

